Set(_cmpNavSelID, 2);
UpdateContext(
    {
        locTskLoading: true,
        locTskTab: "pending",
        locTskExpandedKey: "",
        locTskRerouteOpen: false,
        locTskRerouteKey: "",
        locTskFinishOpen: false,
        locTskFinishKey: ""
    }
);
ClearCollect(colTskSelected, { AssignmentKey: "" });
Clear(colTskSelected);
ClearCollect(colTskPending, nfTskPending);
ClearCollect(colTskCompleted, nfTskCompleted);
UpdateContext({ locTskLoading: false })

IfError(
    UpdateContext(
        {
            locTskRrRes:
                { ok: false, code: "unreachable", message: "Rerouting would reassign this task and log the change to the audit trail. " & nfGateSuffix, requeststatus: "" }
        }
    ),
    UpdateContext(
        {
            locTskRrRes:
                {
                    ok: false,
                    code: "unreachable",
                    message: "Could not reach the workflow. " & FirstError.Message,
                    assignee: ""
                }
        }
    )
);
If(
    !locTskRrRes.ok,
    UpdateContext({ locTskRrBusy: false });
    Notify(locTskRrRes.message, NotificationType.Warning),
    UpdateContext(
        {
            locTskRerouteOpen: false,
            locTskRerouteKey: "",
            locTskRrBusy: false
        }
    );
    // Refresh IS REQUIRED. An earlier comment here said the opposite: that the
    // galleries read the list directly so they would pick the change up on their
    // own. They do read the list, and that is not the same thing.
    //
    // The FLOW changed the row SERVER SIDE, and Canvas holds a client-side cache of
    // 'RequestAssignments' that a server-side write does not invalidate, so formulas
    // kept answering from the old snapshot. The symptom was two figures on this
    // screen disagreeing after a reroute.
    ClearCollect(colTskPending, nfTskPending);
    ClearCollect(colTskCompleted, nfTskCompleted);
    Reset(cmpTskReroute);
    Notify(locTskRrRes.message, NotificationType.Success)
)
// THE REQUEST KEY IS LOOKED UP, not passed. My Tasks holds an AssignmentKey
// and nothing else about the request. AssignmentKey is indexed, so this is a
// single-row delegable read.
//
// NO RELOAD AND NO NAVIGATE. Every gallery and count on this screen reads
// nfTskPending or nfTskCompleted, which query the list directly, so they pick
// the change up on their own. There is no collection here to refresh.

Patch(
    colAssignments,
    LookUp(colAssignments, AssignmentKey = locTskFinishKey),
    {
        StatusKey: "Completed",
        OutcomeKey: locTskFinishOutcome,
        Comments: locTskFinishComment,
        CompletedDate: Today(),
        ActedByEmail: nfUserEmail
    }
);
Collect(
    colAudit,
    {
        ActionKey: "task",
        ActorName: nfUserName,
        Detail: LookUp(colAssignments, AssignmentKey = locTskFinishKey).Goal,
        EntryStamp: Now(),
        Meta: "",
        RequestKey: LookUp(colAssignments, AssignmentKey = locTskFinishKey).RequestKey,
        Title:
            Switch(
                locTskFinishOutcome,
                "Approve", "Task Completed",
                "Reject", "Task Rejected",
                "SendBack", "Task Sent Back",
                "Task Completed"
            )
    }
);
ForAll(
    Filter(
        colPhases,
        RequestKey = LookUp(colAssignments, AssignmentKey = locTskFinishKey).RequestKey
    ) As ph,
    Patch(
        colPhases,
        LookUp(colPhases, PhaseKey = ph.PhaseKey),
        {
            PhaseStatusKey:
                If(
                    CountRows(
                        Filter(
                            colAssignments,
                            PhaseKey = ph.PhaseKey,
                            Required,
                            StatusKey <> "Completed"
                        )
                    ) = 0,
                    "Completed",
                    ph.PhaseStatusKey
                )
        }
    )
);
IfError(
    UpdateContext(
        {
            locTskFinRes:
                { ok: true, code: "ok", message: "", requeststatus: "" }
        }
    ),
    UpdateContext(
        {
            locTskFinRes:
                {
                    ok: false,
                    code: "unreachable",
                    message: "Could not reach the workflow. " & FirstError.Message,
                    requeststatus: ""
                }
        }
    )
);
If(
    locTskFinRes.code = "notactive" || locTskFinRes.code = "unreachable",

    // Nothing was written. Drop the overlay and leave the dialog open so the
    // typed comment survives. Same two codes scrDetails treats this way.
    UpdateContext({ locTskFinBusy: false });
    Notify(locTskFinRes.message, NotificationType.Warning),

    // The flow completed the task and may have advanced the phase, which can
    // change this user's open work. Refresh before anything re-reads: the write
    // was SERVER SIDE and the client-side cache does not notice, so the counts
    // would otherwise disagree with the list.
    ClearCollect(colTskPending, nfTskPending);
    ClearCollect(colTskCompleted, nfTskCompleted);
    UpdateContext(
        {
            locTskFinishOpen: false,
            locTskFinishKey: "",
            locTskFinBusy: false
        }
    );
    Reset(cmpTskFinish);
    Notify(locTskFinRes.message, NotificationType.Success)
)
